theorem.raw:
\label{thr:general-polar}
  Suppose that Assumption~\ref{assumption:X} holds.  Let $\mathcal{H}$ be a
  countable family of measurable functions $h:\mathbb{X}\mapsto\mathbb{R}_+$ such
  that for all $h \in \mathcal{H}$ and $x \in \mathbb{X}$ the function $ t \mapsto
  h(tx)$ is right-continuous (or left-continuous) on $\mathbb{R}_{++}$.

  A $\sigma$-finite measure $\nu$ on $\mathbb{X}$ is $\alpha$-homogeneous and
  satisfies
  \begin{equation}
    \label{eq:nu-h-integral}
    \int_\mathbb{X} h(x) \, \nu(dx) <\infty,\qquad h\in\mathcal{H},
  \end{equation}
  and 
  \begin{equation}
    \label{Eq:nu-support-h}
    \nu\left(\bigcap_{h\in\mathcal{H}} \{x\in\mathbb{X}:\; h(x)=0\}\right)=0
  \end{equation}
  if and only if there exists a probability measure $\pi$ on $\mathbb{X}$
  such that \eqref{Eq:nu-rep} holds, 
  \begin{equation}
    \label{Eq:levy-condition-pi-general}
    \int_{\mathbb{X}}\int_0^\infty h(tx) t^{-(\alpha+1)} \, dt \, \pi(dx) <\infty,
    \qquad h\in\mathcal{H},
  \end{equation}
  and 
  \begin{displaymath}
    \pi\left((0,\infty) \bigcap_{h \in \mathcal{H}} \{x\in\mathbb{X}:\; h(x)=0\}\right)=0. 
  \end{displaymath}

lemma.raw:
\label{lemma:projection}
  Let $\nu$ be a $\sigma$-finite $\alpha$-homogeneous measure on
  $(\mathbb{X}, \mathfrak{B})$ and suppose that $\mathfrak{B}$ is $\nu$-complete.
  \begin{itemize}
  \item[i)] For $B \in \mathfrak{B}$ and a Borel set $I \subseteq \mathbb{R}_{++}$,
    the set $I B$ also belongs to $\mathfrak{B}$.
  \item[ii)] If $\nu([t,u) B) < \infty$ for $B \in \mathfrak{B}$ and $0 < t <
    u < \infty$, then $\nu([s,\infty) B) < \infty$ for all $s > 0$.
\end{itemize}

\label{lemma:non-zero}
  Assume for some $\chi\in\hat{\bK}$ that
  \begin{equation}
    \label{Eq:lim-chi-positive}
    \liminf_{t\downarrow0} \mathrm{Re}\,\chi(tx)>0
  \end{equation}
  for all $x\in\mathbb{K}$.  If $\xi$ is a strictly $\alpha$-stable random
  element, then $\mathbb{E}\chi(\xi)\neq 0$.

proposition.raw:
\label{proposition:renorm}
  Suppose that Assumption~\ref{assumption:U} holds.
  The following are equivalent for a measure $\nu$ on $(\mathbb{X}, \mathfrak{B})$.
  \begin{itemize}
  \item[i)]
    The measure $\nu$ is a nontrivial $\alpha$-homogeneous measure with
    \begin{equation}
      \label{Eq:nu-finite}
      \nu(U_k)<\infty,\qquad k\in\mathbb{N}\,.
    \end{equation}
  \item[ii)] The measure $\nu$ is the push-forward of the measure
    $\pi\otimes\theta_\alpha$ by the map $(x,t)\mapsto tx$, where
    $\pi$ is a probability measure on $\mathbb{X}$ such that
    \begin{equation}
      \label{eq:pi-Sk}
      \int_0^\infty \pi(tU_k)t^{\alpha-1} \, dt < \infty,\qquad k\in\mathbb{N},
    \end{equation}
    and $\theta_\alpha$ is the measure on $\mathbb{R}_{++}$ given by 
    $\theta_\alpha(dt) := \alpha t^{-(\alpha+1)} \, dt$.
  \item[(iii)] For a probability measure $\pi$ on $\mathbb{X}$ such that
    \eqref{eq:pi-Sk} holds,
    \begin{equation}
      \label{Eq:nu-rep}
      \nu(B) = \alpha \int_0^\infty \pi(t B) \, t^{\alpha-1} \, dt
    \end{equation}
    for all $B \in \mathfrak{B}$.
  \end{itemize}

remark.raw:
\label{rem:sphere-from-h}
  If $h_n(tx)\to 0$ as $t\downarrow0$ for all $n\in\mathbb{N}$, then it is
  not necessary to require Assumption~\ref{assumption:X} in
  Theorem~\ref{thr:general-polar}. A measurable transversal can be
  constructed as follows. For each $n\in\mathbb{N}$, let
  \begin{displaymath}
    W_n:=\{x\in\mathbb{X}:\; h_k(x)=0,k<n,\; h_n(x)\neq 0\}.
  \end{displaymath}
Next, partition $W_n$ into measurable sets
  \begin{align*}
    W_{nj}&:=\{x\in W_n:\; \sup_{t>0}
    h_n(tx)\in(2^{-j},2^{-j+1}]\},\qquad j\geq 1,\\
    W_{n0}&:=\{x\in W_n:\; \sup_{t>0}
    h_n(tx)>1\}.
  \end{align*}
  Finally, define
  \begin{displaymath}
    \tau_{nj}(x):=\inf\{t>0:\; h_n(tx)>2^{-j}\},\qquad x\in W_{nj},
  \end{displaymath}
  and
  \begin{displaymath}
    S_{nj}:=\{\tau_{nj}(x)^{-1}x:\; x\in W_{nj}\}. 
  \end{displaymath}
  Then $\mathbb{S}:=\bigcup_{n,j\in\mathbb{N}} S_{nj}$ satisfies
  Assumption~\ref{assumption:X} in the complement of the set
  $\{x\in\mathbb{X}:\; h_n(x)=0,n\in\mathbb{N}\}$.

